# 29b  S1 with and without the 53 Kap plots, whose BYI is one imputed value; BYI percentiles of natural plots without them; height held-out file.
source("scripts/28_common.R"); cat("\nS1 all plots:", round(s1fit(M), 4), " n", nrow(M), "\nS1 without Kap:", round(s1fit(M[Data != "Kap"]), 4), " n", nrow(M[Data != "Kap"]), "; Kap plots in S1:", nrow(M[Data == "Kap"]), "\n")
m2 <- lm(ls ~ lbyi + planted, data = M[Data != "Kap"], weights = w); print(round(summary(m2)$coefficients, 4)); cat("Kap plots: weighted mean ln SDImax", round(M[Data == "Kap", weighted.mean(ls, w)], 3), " exp", round(exp(M[Data == "Kap", weighted.mean(ls, w)])), "; S1 prediction at their BYI", round(s1p(bs, log(64.45216), 0)), "; share of S1 weight held by Kap", round(M[Data == "Kap", sum(w)] / sum(M$w), 3), "\n")
u <- unique(tr[, .(pid, planted, BYI, Data)]); cat("natural BYI percentiles without Kap (10, 50, 90):", round(quantile(u[planted == 0 & Data != "Kap", BYI], c(.1, .5, .9)), 1), "\n"); b2 <- s1fit(M[Data != "Kap"])
cat("SDImax natural at BYI 64, 248, 386: all plots", round(s1p(bs, log(c(64.45, 247.67, 386.18)), 0)), " without Kap", round(s1p(b2, log(c(64.45, 247.67, 386.18)), 0)), "; planted at 121, 156, 309: all", round(s1p(bs, log(c(121.4, 156.1, 308.5)), 1)), " without Kap", round(s1p(b2, log(c(121.4, 156.1, 308.5)), 1)), "\n")
bk <- benchrun(function(x) list(sm = s1p(b2, log(x$byi), x$pl), bg = bg, bm = bm)); cat("benchmark with S1 fitted without Kap (S1 in sample, E4r and E6r of record):\n"); print(sm1(bk)); bk0 <- benchrun(function(x) list(sm = s1p(bs, log(x$byi), x$pl), bg = bg, bm = bm)); cat("same with S1 of record in sample:\n"); print(sm1(bk0))
print(fread("out/E2_cv.csv")[, .(form, n, bias = round(bias, 3), rmse = round(rmse, 3), slope = round(slope, 3), b1_lo = round(b1_lo, 3), b1_hi = round(b1_hi, 3), pass_int, pass_slope)]); cat("29b done\n")
